import {FIT_COUNTS,machiningBudget,fitPointStatus,fitPhaseStatus} from './fabrication-plan.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=v=>Number.isFinite(v)?Number(v.toFixed(3)).toString():'未設定';
const number=(p,k,label,unit='mm',note='')=>`<div class="field full"><label for="fab-${k}">${label}</label><div class="field-wrap"><input id="fab-${k}" name="fab.${k}" type="number" min="0" step="any" inputmode="decimal" value="${p[k]??''}" placeholder="未設定"><span class="field-unit">${unit}</span></div>${note?`<small>${note}</small>`:''}</div>`;
const text=(p,k,label,max=180)=>k==='weldNote'?`<div class="field full"><label for="fab-${k}">${label}</label><textarea id="fab-${k}" name="fab.${k}" maxlength="${max}" rows="3" placeholder="按工藝單填入">${esc(p[k])}</textarea></div>`:`<div class="field full"><label for="fab-${k}">${label}</label><input id="fab-${k}" name="fab.${k}" type="text" maxlength="${max}" value="${esc(p[k])}" placeholder="按工藝單填入"></div>`;
export function fabricationFormMarkup(p){return `<p class="step-description">先保料、再修磨、試配後量根隙；點固後再量一次。</p><div class="fields-grid"><div class="field full"><label for="fab-tool">加工工具</label><select id="fab-tool" name="fab.tool">${[['grinder','砂輪機切割／修磨'],['saw','鋸切'],['plasma','電漿切割'],['other','其他工具']].map(([v,t])=>`<option value="${v}"${p.tool===v?' selected':''}>${t}</option>`).join('')}</select></div>${number(p,'stock','粗切留料：沿支管軸','mm','填入後增加「粗切／修磨」樣帶；取內外緣較深側再留料。')}${number(p,'markError','預估標線最大偏差：沿軸 ±','mm','填非負幅度；未知留白。')}${number(p,'cutError','預估切磨最大偏差：沿軸 ±','mm','填非負幅度；先用試作實測校正。')}${number(p,'kerf','實測切縫寬度','mm','僅記錄；切縫放廢料側，不自動當砂輪中心線。')}</div><output id="fab-budget" class="workshop-budget">${budgetText(p)}</output><details class="field-helper" open><summary>焊接工藝單與接頭要求</summary><div class="fields-grid">${text(p,'wpsId','WPS／工法編號與版次',100)}${text(p,'gapBasis','根隙量測方向／位置')}${number(p,'gapMin','工法根隙下限')}${number(p,'gapMax','工法根隙上限')}${number(p,'bevelAngle','坡口單邊角（工藝記錄）','°')}${number(p,'rootFace','鈍邊（工藝記錄）')}${text(p,'weldNote','焊道尺寸、點固及焊接順序記錄',500)}</div><small>坡口與焊道欄是工藝記錄，尚未生成坡口加工曲面。工法根隙與幾何徑向間隙分開核對。</small></details><p id="fab-errors" class="form-errors" hidden></p><button type="button" id="open-fitup" class="button primary">開啟試配與點固紀錄</button>`;}
export function budgetText(p){try{const b=machiningBudget(p);return b.known?`沿軸最不利剩餘留料 ${fmt(b.remaining)} mm（${fmt(p.stock)} − ${fmt(p.markError)} − ${fmt(p.cutError)}）。${b.remaining<0?'估計偏差大於留料，請調整。':'仍需試配確認。'} 此估算不是根隙或加工保證。`:'填留料、標線與切磨偏差後，顯示沿軸留料估算。未知值保持空白。';}catch{return '請修正加工計畫欄位。';}}
export function fitupDiagram(p){let points='';for(let i=0;i<p.count;i++){const a=i*360/p.count,r=a*Math.PI/180,x=130-76*Math.cos(r),y=105-76*Math.sin(r),selected=p.tackAngles.includes(a);points+=`<circle cx="${x}" cy="${y}" r="${selected?6:3}" fill="${selected?'#bc6b12':'#1d68b5'}"/><text x="${130-94*Math.cos(r)}" y="${109-94*Math.sin(r)}" text-anchor="middle">${p.count<=12?`P${i+1} `:''}${a}°</text>`;}return `<svg viewBox="0 0 260 222" role="img" aria-label="由支管自由端朝接頭看，分點順時針；橙色為點固參考"><circle cx="130" cy="105" r="76" fill="#f2f7fc" stroke="#a5b8cc"/><text x="130" y="95" text-anchor="middle">自由端朝接頭看</text><text x="130" y="115" text-anchor="middle">角度順時針增加</text>${points}<text x="130" y="216" text-anchor="middle">橙色：點固參考母線</text></svg>`;}
export function fitupPanelMarkup(p){return `<div class="fitup-heading"><div><h3>試配 → 點固 → 重新量測</h3><p>0° 沿用魚口樣帶同名母線，由支管自由直端朝接頭看，順時針分點；點分佈不代表焊接順序。根隙按工藝單的方向與位置量測。</p></div><button type="button" id="fabrication-csv" class="button">下載加工／試配 CSV</button></div><div class="fitup-overview"><div id="fitup-svg">${fitupDiagram(p)}</div><div><p id="fitup-pre-summary"></p><p id="fitup-post-summary"></p><label for="fab-count">量測紀錄分點數</label><select id="fab-count" name="fab.count">${FIT_COUNTS.map(n=>`<option${p.count===n?' selected':''}>${n}</option>`).join('')}</select><p class="field-note">更改分點數會清空實測紀錄與點固參考。所填分點只作紀錄，全周檢查依工法執行。</p><label for="fab-edgeCondition">切口狀況</label><select id="fab-edgeCondition" name="fab.edgeCondition"><option value="unknown"${p.edgeCondition==='unknown'?' selected':''}>尚未檢查</option><option value="checked"${p.edgeCondition==='checked'?' selected':''}>已核對切口與量測基準</option><option value="damaged"${p.edgeCondition==='damaged'?' selected':''}>缺肉／切溝／裂紋等，需處置</option></select></div></div><div class="table-scroll"><table class="fitup-table"><thead><tr><th>分點／3D 位置</th><th>試配根隙 mm</th><th>點固後 mm</th><th>點固參考</th><th>量測紀錄狀態</th></tr></thead><tbody>${Array.from({length:p.count},(_,i)=>{const a=i*360/p.count;return `<tr><td><button type="button" class="button fit-point" data-fit-point="${i}">P${i+1} · ${a}°</button></td><td><input name="fab.pre.${i}" type="number" step="any" min="0" inputmode="decimal" value="${p.preGaps[i]??''}" aria-label="P${i+1} 試配根隙" placeholder="未量測"></td><td><input name="fab.post.${i}" type="number" step="any" min="0" inputmode="decimal" value="${p.postGaps[i]??''}" aria-label="P${i+1} 點固後根隙" placeholder="未量測"></td><td><label><input name="fab.tack.${a}" type="checkbox"${p.tackAngles.includes(a)?' checked':''} aria-label="${a}度點固參考"> T${i+1}</label></td><td><span data-fit-status="pre.${i}">${fitPointStatus(p,i).label}</span><br><span data-fit-status="post.${i}">${fitPointStatus(p,i,'post').label}</span></td></tr>`;}).join('')}</tbody></table></div><label class="disposition-label" for="fab-disposition">修整／修復工藝與重測處置紀錄</label><textarea id="fab-disposition" name="fab.disposition" maxlength="500" rows="3" placeholder="記錄核准處置依據；完成後重新量測">${esc(p.disposition)}</textarea><p class="field-note">超出填入範圍時，重新配合或按核准修復工藝處置。填寫處置紀錄不會把超限值改成合格；符合所填分點範圍也不是焊接強度核准。</p><p id="fitup-errors" class="form-errors" hidden></p>`;}
export function phaseText(p,phase){const s=fitPhaseStatus(p,phase);return `${phase==='post'?'點固後':'試配'}：${s.label} · 已填 ${s.measured}/${s.total} 點`;}
